import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.AgentAnimation{Animation: 1, EntityRuntimeID: 300}
SHRUG = bytes.fromhex("01ac02")

# generated by gophertunnel b8bd735:
# &packet.AgentAnimation{Animation: 0}
ARM_SWING = bytes.fromhex("0000")

GOLDENS = [
    pytest.param(v2225.AgentAnimationPacket(anim=v2225.AgentAnimation.SHRUG, runtime_id=300), SHRUG, id="shrug"),
    pytest.param(
        v2225.AgentAnimationPacket(anim=v2225.AgentAnimation.ARM_SWING, runtime_id=0), ARM_SWING, id="arm-swing"
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_agent_animation_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_agent_animation_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
